            get { return new V2i(1, 1); }
        }

        /// <summary>
        /// All elements set to maximum possible value.
        /// </summary>
        public static V2i MaxValue
        {
            get { return new V2i(Constant<int>.ParseableMaxValue, Constant<int>.ParseableMaxValue); }
        }

        /// <summary>
        /// All elements set to minimum possible value.
        /// </summary>
        public static V2i MinValue
        {
            get { return new V2i(Constant<int>.ParseableMinValue, Constant<int>.ParseableMinValue); }
        }

        /// <summary>
        /// Normalized X-axis.
        /// </summary>
        public static V2i XAxis
        {
            get { return new V2i(1, 0); }
        }

        /// <summary>
        /// Normalized Y-axis.
        /// </summary>
        public static V2i YAxis
        {
            get { return new V2i(0, 1); }
        }

        /// <summary>
        /// An array of accessor functions for the coordinates of the vector.
        /// </summary>
        public static readonly Func<V2i, int>[] SelectorArray =
            new Func<V2i, int>[] { v => v.X, v => v.Y };

        /// <summary>
        /// Element getter function.
        /// </summary>
        public static readonly Func<V2i, int, int> Getter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action.
        /// </summary>
        public static readonly ActionRefValVal<V2i, int, int> Setter =
            (ref V2i v, int i, int s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element getter function with long index.
        /// </summary>
        public static readonly Func<V2i, long, int> LongGetter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action with long index.
        /// </summary>
        public static readonly ActionRefValVal<V2i, long, int> LongSetter =
            (ref V2i v, long i, int s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

