        #region Norms

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        public readonly int LengthSquared
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return X * X  + Y * Y ; }
        }

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        public readonly double Length
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                return Fun.Sqrt(X * X  + Y * Y );
            }
        }

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        public readonly int Norm1
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Abs(X) + Fun.Abs(Y); }
        }

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        public readonly double Norm2
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Sqrt(X * X + Y * Y); }
        }

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        public readonly int NormMax
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Max(Fun.Abs(X), Fun.Abs(Y)); }
        }

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        public readonly int NormMin
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Min(Fun.Abs(X), Fun.Abs(Y)); }
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        public readonly V2d Normalized
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                var s = Length; if (s == 0) return V2d.Zero;
                s = 1 / s;
                return new V2d(X * s, Y * s);
            }
        }

        /// <summary>
        /// Vector rotated 90° counter clockwise: (-Y, X)
        /// </summary>
        public readonly V2i Rot90
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return new V2i(-Y, X); }
        }

        /// <summary>
        /// Vector rotated 180° counter clockwise: (-X, -Y)
        /// </summary>
        public readonly V2i Rot180
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return new V2i(-X, -Y); }
        }

        /// <summary>
        /// Vector rotated 270° counter clockwise: (Y, -X)
        /// </summary>
        public readonly V2i Rot270
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return new V2i(Y, -X); }
        }

        #endregion

