        /// Attention: NEVER implement operators &lt;, &lt;=, &gt;=, &gt;,
        /// since these are not defined in a Vector space.
        /// Use AllSmaller() and similar comparators!
        #endregion

        #region Comparisons

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V2i a, V2i b)
        {
            return a.X == b.X && a.Y == b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V2i v, int s)
        {
            return v.X == s && v.Y == s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(int s, V2i v)
        {
            return s == v.X && s == v.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V2i a, V2i b)
        {
            return a.X != b.X || a.Y != b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V2i v, int s)
        {
            return v.X != s || v.Y != s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(int s, V2i v)
        {
            return s != v.X || s != v.Y;
        }

        #endregion

        #region IEquatable<V2i> Members

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly bool Equals(V2i other)
        {
            return X.Equals(other.X) && Y.Equals(other.Y);
        }

        #endregion

        #region Overrides

        public override readonly string ToString()
        {
            return ToString(null, CultureInfo.InvariantCulture);
        }

        public readonly string ToString(string format)
        {
            return ToString(format, CultureInfo.InvariantCulture);
        }

        public readonly string ToString(string format, IFormatProvider fp)
        {
            return ToString(format, fp, "[", ", ", "]");
        }

        /// <summary>
        /// Outputs e.g. a 3D-Vector in the form "(begin)x(between)y(between)z(end)".
        /// </summary>
        public readonly string ToString(string format, IFormatProvider fp, string begin, string between, string end)
        {
            if (fp == null) fp = CultureInfo.InvariantCulture;
            return begin + X.ToString(format, fp)  + between + Y.ToString(format, fp)  + end;
        }

        public override readonly int GetHashCode()
        {
            return HashCode.GetCombined(X, Y);
        }

        public override readonly bool Equals(object other)
            => (other is V2i o) ? Equals(o) : false;

        public readonly Text ToText(int bracketLevel = 1)
        {
            return
                ((bracketLevel == 1 ? "[" : "")
                + X.ToString(null, CultureInfo.InvariantCulture)  + ", " 
                + Y.ToString(null, CultureInfo.InvariantCulture) 
                + (bracketLevel == 1 ? "]" : "")).ToText();
        }

        #endregion

        #region Parsing

        public static V2i Parse(string s)
        {
            var x = s.NestedBracketSplitLevelOne().ToArray();
            return new V2i(
                int.Parse(x[0], CultureInfo.InvariantCulture), 
                int.Parse(x[1], CultureInfo.InvariantCulture)
            );
        }

        public static V2i Parse(Text t)
        {
            return t.NestedBracketSplit(1, Text<int>.Parse, V2i.Setter);
        }

        public static V2i Parse(Text t, int bracketLevel)
        {
            return t.NestedBracketSplit(bracketLevel, Text<int>.Parse, V2i.Setter);
        }

        #endregion

