        #endregion

        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (int)value; }
        }

        #endregion

        #region ISize2i Members

        public readonly V2i Size2i { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 2; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (int)value;
        }

        #endregion

    }

    public class V2iEqualityComparer : IEqualityComparer<V2i>
    {
        public static V2iEqualityComparer Default
            => new V2iEqualityComparer();

        #region IEqualityComparer<V2i> Members

        public bool Equals(V2i v0, V2i v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V2i v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

    public static partial class Fun
    {
        #region Min and Max

        /// <summary>
        /// Applies Fun.Min to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2i Min(this V2i a, V2i b)
        {
            return new V2i(Min(a.X, b.X), Min(a.Y, b.Y));
        }

