        }

        /// <summary>
        /// Uses UniformIntNonZero() to generate the elements of a V2i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2i UniformV2iNonZero(this IRandomUniform rnd)
        {
