        /// <summary>
        /// Uses UniformInt(int) to generate the elements of a V2i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2i UniformV2i(this IRandomUniform rnd, int size)
        {
            return new V2i(rnd.UniformInt(size), rnd.UniformInt(size));
        }

        /// <summary>
