        #region Comparisons

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V2ui a, V2ui b)
        {
            return a.X == b.X && a.Y == b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V2ui v, uint s)
        {
            return v.X == s && v.Y == s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(uint s, V2ui v)
        {
            return s == v.X && s == v.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V2ui a, V2ui b)
        {
            return a.X != b.X || a.Y != b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V2ui v, uint s)
        {
            return v.X != s || v.Y != s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(uint s, V2ui v)
        {
            return s != v.X || s != v.Y;
        }

