        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (uint)value; }
        }

        #endregion

        #region ISize2ui Members

        public readonly V2ui Size2ui { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 2; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (uint)value;
        }

        #endregion

    }

    public class V2uiEqualityComparer : IEqualityComparer<V2ui>
    {
        public static V2uiEqualityComparer Default
            => new V2uiEqualityComparer();

        #region IEqualityComparer<V2ui> Members

        public bool Equals(V2ui v0, V2ui v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V2ui v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

