        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (long)value; }
        }

        #endregion

        #region ISize2l Members

        public readonly V2l Size2l { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 2; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (long)value;
        }

        #endregion

    }

    public class V2lEqualityComparer : IEqualityComparer<V2l>
    {
        public static V2lEqualityComparer Default
            => new V2lEqualityComparer();

        #region IEqualityComparer<V2l> Members

        public bool Equals(V2l v0, V2l v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V2l v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

