    public static class IRandomUniformV2lExtensions
    {
        #region IRandomUniform extensions for V2l

        /// <summary>
        /// Uses UniformLong() to generate the elements of a V2l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2l UniformV2l(this IRandomUniform rnd)
        {
            return new V2l(rnd.UniformLong(), rnd.UniformLong());
        }

        /// <summary>
        /// Uses UniformLongNonZero() to generate the elements of a V2l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
