        }

        /// <summary>
        /// Returns the index of the largest dimension of the vector.
        /// </summary>
        public readonly int MajorDim
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                return X >= Y ? 0 : 1;
            }
        }

        /// <summary>
        /// Returns the index of the smallest dimension of the vector.
        /// </summary>
        public readonly int MinorDim
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                return X <= Y ? 0 : 1;
            }
        }

        /// <summary>
        /// Returns the minimum element of the vector.
        /// </summary>
        public readonly float MinElement
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.Min(X, Y);
        }

        /// <summary>
        /// Returns the maximum element of the vector.
        /// </summary>
        public readonly float MaxElement
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.Max(X, Y);
        }

        public readonly bool AnyFinite
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.IsFinite(X) || Fun.IsFinite(Y);
        }

        public readonly bool AllFinite
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.IsFinite(X) && Fun.IsFinite(Y);
        }

        public readonly bool AnyNaN
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsNaN(X) || float.IsNaN(Y);
        }

        public readonly bool AllNaN
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsNaN(X) && float.IsNaN(Y);
        }

        public readonly bool AnyInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsInfinity(X) || float.IsInfinity(Y);
        }

        public readonly bool AllInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsInfinity(X) && float.IsInfinity(Y);
        }

        public readonly bool AnyPositiveInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsPositiveInfinity(X) || float.IsPositiveInfinity(Y);
        }

        public readonly bool AllPositiveInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsPositiveInfinity(X) && float.IsPositiveInfinity(Y);
        }

        public readonly bool AnyNegativeInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsNegativeInfinity(X) || float.IsNegativeInfinity(Y);
        }

        public readonly bool AllNegativeInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => float.IsNegativeInfinity(X) && float.IsNegativeInfinity(Y);
        }

        public readonly bool AnyTiny
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.IsTiny(X) || Fun.IsTiny(Y);
        }

        public readonly bool AllTiny
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => Fun.IsTiny(X) && Fun.IsTiny(Y);
        }

        /// <summary>
        /// Returns true if the absolute value of each component of the vector is smaller than Constant&lt;float&gt;.PositiveTinyValue, false otherwise.
        /// </summary>
        public readonly bool IsTiny
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => AllTiny;
        }

        /// <summary>
        /// Returns true if any component of the vector is NaN, false otherwise.
        /// </summary>
        public readonly bool IsNaN
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => AnyNaN;
        }

        /// <summary>
        /// Returns true if any component of the vector is infinite (positive or negative), false otherwise.
        /// </summary>
        public readonly bool IsInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => AnyInfinity;
        }

        /// <summary>
        /// Returns true if any component of the vector is infinite and positive, false otherwise.
        /// </summary>
        public readonly bool IsPositiveInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => AnyPositiveInfinity;
        }

        /// <summary>
        /// Returns true if any component of the vector is infinite and negative, false otherwise.
        /// </summary>
        public readonly bool IsNegativeInfinity
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => AnyNegativeInfinity;
        }

        /// <summary>
        /// Returns whether all components of the vector are finite (i.e. not NaN and not infinity).
        /// </summary>
        public readonly bool IsFinite
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => !(IsInfinity || IsNaN);
        }

