        #region Constants

        /// <summary>
        /// Number of elements in this vector.
        /// </summary>
        public const int Dimension = 2;

        /// <summary>
        /// All elements zero.
        /// </summary>
        public static V2f Zero
        {
            get { return new V2f(0, 0); }
        }

        /// <summary>
        /// All elements half.
        /// </summary>
        public static V2f Half
        {
            get { return new V2f(0.5, 0.5); }
        }

        /// <summary>
        /// All elements one.
        /// </summary>
        public static V2f One
        {
            get { return new V2f(1, 1); }
        }

        /// <summary>
        /// All elements set to maximum possible value.
        /// </summary>
        public static V2f MaxValue
        {
            get { return new V2f(Constant<float>.ParseableMaxValue, Constant<float>.ParseableMaxValue); }
        }

        /// <summary>
        /// All elements set to minimum possible value.
        /// </summary>
        public static V2f MinValue
        {
            get { return new V2f(Constant<float>.ParseableMinValue, Constant<float>.ParseableMinValue); }
        }

         /// <summary>
        /// All elements set to negative infinity.
        /// </summary>
        public static V2f NegativeInfinity
        {
            get { return new V2f(float.NegativeInfinity, float.NegativeInfinity); }
        }

        /// <summary>
        /// All elements set to positive infinity.
        /// </summary>
        public static V2f PositiveInfinity
        {
            get { return new V2f(float.PositiveInfinity, float.PositiveInfinity); }
        }

        /// <summary>
        /// All elements set to NaN.
        /// </summary>
        public static V2f NaN
        {
            get { return new V2f(float.NaN, float.NaN); }
        }

        /// <summary>
        /// Normalized X-axis.
        /// </summary>
        public static V2f XAxis
        {
            get { return new V2f(1, 0); }
        }

        /// <summary>
        /// Normalized Y-axis.
        /// </summary>
        public static V2f YAxis
        {
            get { return new V2f(0, 1); }
        }

        /// <summary>
        /// An array of accessor functions for the coordinates of the vector.
        /// </summary>
        public static readonly Func<V2f, float>[] SelectorArray =
            new Func<V2f, float>[] { v => v.X, v => v.Y };

        /// <summary>
        /// Element getter function.
        /// </summary>
        public static readonly Func<V2f, int, float> Getter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action.
        /// </summary>
        public static readonly ActionRefValVal<V2f, int, float> Setter =
            (ref V2f v, int i, float s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element getter function with long index.
        /// </summary>
        public static readonly Func<V2f, long, float> LongGetter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action with long index.
        /// </summary>
        public static readonly ActionRefValVal<V2f, long, float> LongSetter =
            (ref V2f v, long i, float s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

        #endregion

