        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (float)value; }
        }

        #endregion

        #region ISize2f Members

        public readonly V2f Size2f { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 2; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (float)value;
        }

        #endregion

    }

    public class V2fEqualityComparer : IEqualityComparer<V2f>
    {
        public static V2fEqualityComparer Default
            => new V2fEqualityComparer();

        #region IEqualityComparer<V2f> Members

        public bool Equals(V2f v0, V2f v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V2f v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

