    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float LengthSquared(V2f v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Length(V2f v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Normalizes the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Normalize(this ref V2f v)
        {
            var s = v.Length; if (s == 0) return;
            s = 1 / s;
            v.X *= s;
            v.Y *= s;
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f Normalized(V2f v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm1(V2f v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm2(V2f v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMax(V2f v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMin(V2f v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm(this V2f v, float p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceSquared(this V2f a, V2f b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V2f a, V2f b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance1(this V2f a, V2f b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V2f a, V2f b, float p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMax(this V2f a, V2f b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMin(this V2f a, V2f b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V2f query, V2f p0, V2f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            if (t <= 0) { return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V2f query, V2f p0, V2f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V2f query, V2f p0, V2f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            if (t <= 0) { t = 0; return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { t = 1; return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V2f query, V2f p0, V2f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        #endregion

        #region Operations

        /// <summary>
        /// Returns a vector that is orthogonal to the given one (i.e. {x,y} -> {-y,x}).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f Orthogonal(V2f v)
            => v.Orthogonal;

        /// <summary>
        /// Gets a copy of the given vector containing the reciprocal (1/x) of each element.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f Reciprocal(V2f v)
            => v.Reciprocal;

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V2f v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 2x2 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M22f Outer(this V2f a, V2f b)
        {
            return new M22f(
                        a.X * b.X, a.X * b.Y, 
                        a.Y * b.X, a.Y * b.Y);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Dot(this V2f a, V2f b)
        {
            return a.X * b.X + a.Y * b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V2f v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeY;
            return flags;
        }

        /// <summary>
        /// Returns the reflection direction of the given vector v (pointing to the surface) for the given normal (should be normalized).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f Reflect(this V2f v, V2f normal)
        {
            return v - 2 * v.Dot(normal) * normal;
        }

        /// <summary>
        /// Returns the refraction direction of the given vector v (pointing to the surface) for the given normal and ratio of refraction indices (n_out / n_in).
        /// Both the input vectors should be normalized.
        /// Returns a zero-vector in case of total internal reflection.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f Refract(this V2f v, V2f normal, float eta)
        {
            var t = v.Dot(normal);
            var k = 1 - eta * eta * (1 - t * t);

            if (k < 0)
            {
                return V2f.Zero;
            }
            else
            {
                return eta * v - (eta * t + Fun.Sqrt(k)) * normal;
            }
        }

        /// <summary>
        /// Returns the cross product of vector a.
        /// In 2D the cross product is simply a vector that is normal
        /// to the given vector (i.e. {x,y} -> {-y,x})
        /// </summary>
        public static V2f Cross(this V2f a)
        {
            return new V2f(-a.Y, a.X);
        }

