    public static class IRandomUniformV2fExtensions
    {
        #region IRandomUniform extensions for V2f

        /// <summary>
        /// Uses UniformFloat() to generate the elements of a V2f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2f(this IRandomUniform rnd)
        {
            return new V2f(rnd.UniformFloat(), rnd.UniformFloat());
        }

        /// <summary>
        /// Uses UniformFloat() to generate the elements of a V2f
        /// vector within the given Box2f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2f(this IRandomUniform rnd, Box2f box)
        {
            return new V2f(box.Min.X + rnd.UniformFloat() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloat() * (box.Max.Y - box.Min.Y));
        }

        /// <summary>
        /// Uses UniformFloatClosed() to generate the elements of a V2f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2fClosed(this IRandomUniform rnd)
        {
            return new V2f(rnd.UniformFloatClosed(), rnd.UniformFloatClosed());
        }

        /// <summary>
        /// Uses UniformFloatClosed() to generate the elements of a V2f
        /// vector within the given Box2f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2fClosed(this IRandomUniform rnd, Box2f box)
        {
            return new V2f(box.Min.X + rnd.UniformFloatClosed() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloatClosed() * (box.Max.Y - box.Min.Y));
        }

        /// <summary>
        /// Uses UniformFloatOpen() to generate the elements of a V2f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2fOpen(this IRandomUniform rnd)
        {
            return new V2f(rnd.UniformFloatOpen(), rnd.UniformFloatOpen());
        }

        /// <summary>
        /// Uses UniformFloatOpen() to generate the elements of a V2f
        /// vector within the given Box2f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2fOpen(this IRandomUniform rnd, Box2f box)
        {
            return new V2f(box.Min.X + rnd.UniformFloatOpen() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloatOpen() * (box.Max.Y - box.Min.Y));
        }

        /// <summary>
        /// Returns a uniformly distributed vector (corresponds to a
        /// uniformly distributed point on the unit circle). Uses UniformFloat() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2f UniformV2fDirection(this IRandomUniform rnd)
        {
            float phi = rnd.UniformFloat() * ConstantF.PiTimesTwo;
            return new V2f(Fun.Cos(phi), Fun.Sin(phi));
        }

        #endregion
    }

