        /// <summary>
        /// Sets the elements of a vector to the given int elements.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void Set(int x, int y)
        {
            X = (double)x;
            Y = (double)y;
        }

