        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (double)value; }
        }

        #endregion

        #region ISize2d Members

        public readonly V2d Size2d { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 2; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (double)value;
        }

        #endregion

    }

    public class V2dEqualityComparer : IEqualityComparer<V2d>
    {
        public static V2dEqualityComparer Default
            => new V2dEqualityComparer();

        #region IEqualityComparer<V2d> Members

        public bool Equals(V2d v0, V2d v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V2d v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

    public static partial class Fun
    {
        #region Min and Max

        /// <summary>
        /// Applies Fun.Min to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Min(this V2d a, V2d b)
        {
            return new V2d(Min(a.X, b.X), Min(a.Y, b.Y));
        }

