        #region ApproximateEquals

        /// <summary>
        /// Returns whether the given vectors are equal within the given tolerance.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool ApproximateEquals(this V2d a, V2d b, double tolerance)
        {
            return ApproximateEquals(a.X, b.X, tolerance) && ApproximateEquals(a.Y, b.Y, tolerance);
        }

        /// <summary>
        /// Returns whether the given vectors are equal within
        /// Constant{double}.PositiveTinyValue.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool ApproximateEquals(this V2d a, V2d b)
        {
            return ApproximateEquals(a, b, Constant<double>.PositiveTinyValue);
        }


