    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double LengthSquared(V2d v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Length(V2d v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Normalizes the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Normalize(this ref V2d v)
        {
            var s = v.Length; if (s == 0) return;
            s = 1 / s;
            v.X *= s;
            v.Y *= s;
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Normalized(V2d v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm1(V2d v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm2(V2d v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double NormMax(V2d v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double NormMin(V2d v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm(this V2d v, double p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceSquared(this V2d a, V2d b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V2d a, V2d b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance1(this V2d a, V2d b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V2d a, V2d b, double p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceMax(this V2d a, V2d b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceMin(this V2d a, V2d b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V2d query, V2d p0, V2d p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            if (t <= 0) { return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V2d query, V2d p0, V2d p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V2d query, V2d p0, V2d p1, out double t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            if (t <= 0) { t = 0; return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { t = 1; return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V2d query, V2d p0, V2d p1, out double t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        #endregion

        #region Operations

        /// <summary>
        /// Returns a vector that is orthogonal to the given one (i.e. {x,y} -> {-y,x}).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Orthogonal(V2d v)
            => v.Orthogonal;

        /// <summary>
        /// Gets a copy of the given vector containing the reciprocal (1/x) of each element.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Reciprocal(V2d v)
            => v.Reciprocal;

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V2d v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 2x2 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M22d Outer(this V2d a, V2d b)
        {
            return new M22d(
                        a.X * b.X, a.X * b.Y, 
                        a.Y * b.X, a.Y * b.Y);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Dot(this V2d a, V2d b)
        {
            return a.X * b.X + a.Y * b.Y;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V2d v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > Constant<double>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < Constant<double>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > Constant<double>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < Constant<double>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeY;
            return flags;
        }

        /// <summary>
        /// Returns the reflection direction of the given vector v (pointing to the surface) for the given normal (should be normalized).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Reflect(this V2d v, V2d normal)
        {
            return v - 2 * v.Dot(normal) * normal;
        }

        /// <summary>
        /// Returns the refraction direction of the given vector v (pointing to the surface) for the given normal and ratio of refraction indices (n_out / n_in).
        /// Both the input vectors should be normalized.
        /// Returns a zero-vector in case of total internal reflection.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d Refract(this V2d v, V2d normal, double eta)
        {
            var t = v.Dot(normal);
            var k = 1 - eta * eta * (1 - t * t);

            if (k < 0)
            {
                return V2d.Zero;
            }
            else
            {
                return eta * v - (eta * t + Fun.Sqrt(k)) * normal;
            }
        }

        /// <summary>
        /// Returns the cross product of vector a.
        /// In 2D the cross product is simply a vector that is normal
        /// to the given vector (i.e. {x,y} -> {-y,x})
        /// </summary>
        public static V2d Cross(this V2d a)
        {
            return new V2d(-a.Y, a.X);
        }

        #endregion

        #region Comparisons

        /// <summary>
        /// Returns whether ALL elements of a are Smaller the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(this V2d a, V2d b)
        {
            return (a.X < b.X && a.Y < b.Y);
        }

        /// <summary>
        /// Returns whether ALL elements of v are Smaller s.
