    public static class IRandomUniformV2dExtensions
    {
        #region IRandomUniform extensions for V2d

        /// <summary>
        /// Uses UniformDouble() to generate the elements of a V2d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V2d UniformV2d(this IRandomUniform rnd)
        {
            return new V2d(rnd.UniformDouble(), rnd.UniformDouble());
        }

        /// <summary>
