            var maximum = vectorArray[0].Z;
            int maxIndex = 0;
            if (count == 0) count = vectorArray.Length;
            for (int i = 1; i < count; i++)
            {
                var p = vectorArray[i].Z;
                if (p > maximum) { maximum = p; maxIndex = i; }
            }
            return maxIndex;
        }

        /// <summary>
        /// Returns the index of the element with the maximal Z coordinate
        /// within the array.
        /// </summary>
        public static long LongIndexOfMaxZ(this V3i[] vectorArray, long count = 0)
        {
            var maximum = vectorArray[0].Z;
            long maxIndex = 0;
            if (count == 0) count = vectorArray.LongLength;
            for (long i = 1; i < count; i++)
            {
                var p = vectorArray[i].Z;
                if (p > maximum) { maximum = p; maxIndex = i; }
            }
            return maxIndex;
