    public static class IRandomUniformV3iExtensions
    {
        #region IRandomUniform extensions for V3i

        /// <summary>
        /// Uses UniformInt() to generate the elements of a V3i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3i UniformV3i(this IRandomUniform rnd)
        {
            return new V3i(rnd.UniformInt(), rnd.UniformInt(), rnd.UniformInt());
        }

        /// <summary>
        /// Uses UniformIntNonZero() to generate the elements of a V3i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3i UniformV3iNonZero(this IRandomUniform rnd)
        {
            return new V3i(rnd.UniformIntNonZero(), rnd.UniformIntNonZero(), rnd.UniformIntNonZero());
        }

        /// <summary>
        /// Uses UniformInt(int) to generate the elements of a V3i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3i UniformV3i(this IRandomUniform rnd, int size)
        {
            return new V3i(rnd.UniformInt(size), rnd.UniformInt(size), rnd.UniformInt(size));
        }

        /// <summary>
        /// Uses UniformInt(int) to generate the elements of a V3i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3i UniformV3i(this IRandomUniform rnd, V3i size)
        {
            return new V3i(rnd.UniformInt(size.X), rnd.UniformInt(size.Y), rnd.UniformInt(size.Z));
        }

        #endregion
    }

