        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (uint)value; }
        }

        #endregion

        #region ISize3ui Members

        public readonly V3ui Size3ui { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 3; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (uint)value;
        }

        #endregion

    }

    public class V3uiEqualityComparer : IEqualityComparer<V3ui>
    {
        public static V3uiEqualityComparer Default
            => new V3uiEqualityComparer();

        #region IEqualityComparer<V3ui> Members

        public bool Equals(V3ui v0, V3ui v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V3ui v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

