            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint Norm1(V3ui v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm2(V3ui v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint NormMax(V3ui v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint NormMin(V3ui v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm(this V3ui v, double p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p) + 
                Fun.Abs(v.Z).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint DistanceSquared(this V3ui a, V3ui b)
            => Fun.Square((a.X < b.X) ? (b.X - a.X) : (a.X - b.X)) + Fun.Square((a.Y < b.Y) ? (b.Y - a.Y) : (a.Y - b.Y)) + Fun.Square((a.Z < b.Z) ? (b.Z - a.Z) : (a.Z - b.Z));

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V3ui a, V3ui b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint Distance1(this V3ui a, V3ui b)
            => ((a.X < b.X) ? (b.X - a.X) : (a.X - b.X)) + ((a.Y < b.Y) ? (b.Y - a.Y) : (a.Y - b.Y)) + ((a.Z < b.Z) ? (b.Z - a.Z) : (a.Z - b.Z));

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V3ui a, V3ui b, double p)
            => (((a.X < b.X) ? (b.X - a.X) : (a.X - b.X)).Pow(p) + ((a.Y < b.Y) ? (b.Y - a.Y) : (a.Y - b.Y)).Pow(p) + ((a.Z < b.Z) ? (b.Z - a.Z) : (a.Z - b.Z)).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint DistanceMax(this V3ui a, V3ui b)
            => Fun.Max(((a.X < b.X) ? (b.X - a.X) : (a.X - b.X)), ((a.Y < b.Y) ? (b.Y - a.Y) : (a.Y - b.Y)), ((a.Z < b.Z) ? (b.Z - a.Z) : (a.Z - b.Z)));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint DistanceMin(this V3ui a, V3ui b)
            => Fun.Min(((a.X < b.X) ? (b.X - a.X) : (a.X - b.X)), ((a.Y < b.Y) ? (b.Y - a.Y) : (a.Y - b.Y)), ((a.Z < b.Z) ? (b.Z - a.Z) : (a.Z - b.Z)));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V3ui query, V3ui p0, V3ui p1)
        {
            return DistanceToLine((V3d) query, (V3d) p0, (V3d) p1);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
