        /// <summary>
        /// Compare x-coordinate before y-coordinate, aso.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int LexicalCompare(this V3ui v0, V3ui v1)
        {
            if (v0.X < v1.X) return -1;
            if (v0.X > v1.X) return +1;
            if (v0.Y < v1.Y) return -1;
            if (v0.Y > v1.Y) return +1;
            if (v0.Z < v1.Z) return -1;
            if (v0.Z > v1.Z) return +1;
            return 0;
        }

