    public static class IRandomUniformV3uiExtensions
    {
        #region IRandomUniform extensions for V3ui

        /// <summary>
        /// Uses UniformUInt() to generate the elements of a V3ui vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3ui UniformV3ui(this IRandomUniform rnd)
        {
            return new V3ui(rnd.UniformUInt(), rnd.UniformUInt(), rnd.UniformUInt());
        }

        #endregion
    }

