    #region V3l

    [DataContract]
    [Serializable]
    [StructLayout(LayoutKind.Sequential)]
    public partial struct V3l : IVector<double>, ISize3l, IFormattable, IEquatable<V3l>
    {
        [DataMember]
        public long X;
        [DataMember]
        public long Y;
        [DataMember]
        public long Z;

        #region Constructors

        /// <summary>
        /// Creates a new vector from given <see cref="int"/> elements.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(int x, int y, int z)
        {
            X = (long)x;
            Y = (long)y;
            Z = (long)z;
        }

        /// <summary>
        /// Creates a new vector by assigning the given <see cref="int"/> to all elements.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(int v)
        {
            X = (long)v;
            Y = (long)v;
            Z = (long)v;
        }

        /// <summary>
        /// Creates a new vector from the given array.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(int[] a)
        {
            X = (long)a[0];
            Y = (long)a[1];
            Z = (long)a[2];
        }

        /// <summary>
        /// Creates a new vector from given array, starting at specified index.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(int[] a, int start)
        {
            X = (long)a[start + 0];
            Y = (long)a[start + 1];
            Z = (long)a[start + 2];
        }

        /// <summary>
        /// Creates a new vector from the given <see cref="int"/> and <see cref="V2i"/>.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(int a, V2i b)
        {
            X = (long)a;
            Y = (long)b.X;
            Z = (long)b.Y;
        }

        /// <summary>
        /// Creates a new vector from the given <see cref="V2i"/> and <see cref="int"/>.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(V2i a, int b)
        {
            X = (long)a.X;
            Y = (long)a.Y;
            Z = (long)b;
        }

        /// <summary>
        /// Creates a new vector from given <see cref="uint"/> elements.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(uint x, uint y, uint z)
        {
            X = (long)x;
            Y = (long)y;
            Z = (long)z;
        }

        /// <summary>
        /// Creates a new vector by assigning the given <see cref="uint"/> to all elements.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public V3l(uint v)
        {
            X = (long)v;
            Y = (long)v;
            Z = (long)v;
        }

