        /// <summary>
        /// Element getter function.
        /// </summary>
        public static readonly Func<V3l, int, long> Getter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    case 2: return v.Z;
                    default: throw new IndexOutOfRangeException();
                }
            };

