        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (long)value; }
        }

        #endregion

        #region ISize3l Members

        public readonly V3l Size3l { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 3; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (long)value;
        }

        #endregion

    }

    public class V3lEqualityComparer : IEqualityComparer<V3l>
    {
        public static V3lEqualityComparer Default
            => new V3lEqualityComparer();

        #region IEqualityComparer<V3l> Members

        public bool Equals(V3l v0, V3l v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V3l v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

