    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long LengthSquared(V3l v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Length(V3l v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d Normalized(V3l v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Norm1(V3l v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm2(V3l v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long NormMax(V3l v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long NormMin(V3l v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm(this V3l v, double p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p) + 
                Fun.Abs(v.Z).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceSquared(this V3l a, V3l b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y) + Fun.Square(b.Z - a.Z);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V3l a, V3l b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Distance1(this V3l a, V3l b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y) + Fun.Abs(b.Z - a.Z);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V3l a, V3l b, double p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p) + Fun.Abs(b.Z - a.Z).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceMax(this V3l a, V3l b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceMin(this V3l a, V3l b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V3l query, V3l p0, V3l p1)
        {
            return DistanceToLine((V3d) query, (V3d) p0, (V3d) p1);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V3l query, V3l p0, V3l p1)
        {
            return DistanceToInfiniteLine((V3d) query, (V3d) p0, (V3d) p1);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V3l query, V3l p0, V3l p1, out double t)
        {
            return DistanceToLine((V3d) query, (V3d) p0, (V3d) p1, out t);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V3l query, V3l p0, V3l p1, out double t)
        {
            return DistanceToInfiniteLine((V3d) query, (V3d) p0, (V3d) p1, out t);
        }

        #endregion

        #region Operations

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V3l v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
            v.Z = -v.Z;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 3x3 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M33l Outer(this V3l a, V3l b)
        {
            return new M33l(
                        a.X * b.X, a.X * b.Y, a.X * b.Z, 
                        a.Y * b.X, a.Y * b.Y, a.Y * b.Z, 
                        a.Z * b.X, a.Z * b.Y, a.Z * b.Z);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Dot(this V3l a, V3l b)
        {
            return a.X * b.X + a.Y * b.Y + a.Z * b.Z;
        }

        /// <summary>
        /// Returns the skew-symmetric "cross" matrix (A^T = -A) of the vector v.
        /// </summary>
        public static M33l CrossMatrix(this V3l v)
        {
            return new M33l(0, -v.Z, +v.Y,
                            +v.Z, 0, -v.X,
                            -v.Y, +v.X, 0);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V3l v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > 0) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < 0) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > 0) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < 0) flags |= Aardbase.DirFlags.NegativeY;
            if (v.Z > 0) flags |= Aardbase.DirFlags.PositiveZ;
            if (v.Z < 0) flags |= Aardbase.DirFlags.NegativeZ;
            return flags;
        }

        /// <summary>
        /// Returns the cross product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3l Cross(this V3l a, V3l b)
        {
            return new V3l(
            a.Y * b.Z - a.Z * b.Y,
            a.Z * b.X - a.X * b.Z,
            a.X * b.Y - a.Y * b.X
            );
        }

        #endregion

        #region Comparisons

        /// <summary>
        /// Returns whether ALL elements of a are Smaller the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(this V3l a, V3l b)
        {
            return (a.X < b.X && a.Y < b.Y && a.Z < b.Z);
        }

        /// <summary>
        /// Returns whether ALL elements of v are Smaller s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(this V3l v, long s)
        {
            return (v.X < s && v.Y < s && v.Z < s);
        }

        /// <summary>
        /// Returns whether a is Smaller ALL elements of v.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(long s, V3l v)
        {
            return (s < v.X && s < v.Y && s < v.Z);
        }

        /// <summary>
        /// Returns whether AT LEAST ONE element of a is Smaller the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnySmaller(this V3l a, V3l b)
        {
            return (a.X < b.X || a.Y < b.Y || a.Z < b.Z);
        }

        /// <summary>
        /// Returns whether AT LEAST ONE element of v is Smaller s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnySmaller(this V3l v, long s)
        {
            return (v.X < s || v.Y < s || v.Z < s);
        }

        /// <summary>
        /// Returns whether a is Smaller AT LEAST ONE element of v.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnySmaller(long s, V3l v)
        {
            return (s < v.X || s < v.Y || s < v.Z);
        }

        /// <summary>
        /// Returns whether ALL elements of a are Greater the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllGreater(this V3l a, V3l b)
        {
            return (a.X > b.X && a.Y > b.Y && a.Z > b.Z);
        }

        /// <summary>
        /// Returns whether ALL elements of v are Greater s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllGreater(this V3l v, long s)
        {
            return (v.X > s && v.Y > s && v.Z > s);
        }

        /// <summary>
        /// Returns whether a is Greater ALL elements of v.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllGreater(long s, V3l v)
        {
            return (s > v.X && s > v.Y && s > v.Z);
        }

        /// <summary>
        /// Returns whether AT LEAST ONE element of a is Greater the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnyGreater(this V3l a, V3l b)
        {
            return (a.X > b.X || a.Y > b.Y || a.Z > b.Z);
        }

        /// <summary>
        /// Returns whether AT LEAST ONE element of v is Greater s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnyGreater(this V3l v, long s)
        {
            return (v.X > s || v.Y > s || v.Z > s);
        }

        /// <summary>
        /// Returns whether a is Greater AT LEAST ONE element of v.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnyGreater(long s, V3l v)
        {
            return (s > v.X || s > v.Y || s > v.Z);
        }

        /// <summary>
        /// Returns whether ALL elements of a are SmallerOrEqual the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmallerOrEqual(this V3l a, V3l b)
        {
            return (a.X <= b.X && a.Y <= b.Y && a.Z <= b.Z);
        }

        /// <summary>
        /// Returns whether ALL elements of v are SmallerOrEqual s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
