        public static readonly Func<V3f, float>[] SelectorArray =
            new Func<V3f, float>[] { v => v.X, v => v.Y, v => v.Z };

        /// <summary>
        /// Element getter function.
        /// </summary>
        public static readonly Func<V3f, int, float> Getter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    case 2: return v.Z;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action.
        /// </summary>
        public static readonly ActionRefValVal<V3f, int, float> Setter =
            (ref V3f v, int i, float s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    case 2: v.Z = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element getter function with long index.
        /// </summary>
