        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (float)value; }
        }

        #endregion

        #region ISize3f Members

        public readonly V3f Size3f { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 3; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (float)value;
        }

        #endregion

    }

    public class V3fEqualityComparer : IEqualityComparer<V3f>
    {
        public static V3fEqualityComparer Default
            => new V3fEqualityComparer();

        #region IEqualityComparer<V3f> Members

        public bool Equals(V3f v0, V3f v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V3f v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

