    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float LengthSquared(V3f v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Length(V3f v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Normalizes the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Normalize(this ref V3f v)
        {
            var s = v.Length; if (s == 0) return;
            s = 1 / s;
            v.X *= s;
            v.Y *= s;
            v.Z *= s;
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f Normalized(V3f v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm1(V3f v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm2(V3f v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMax(V3f v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMin(V3f v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm(this V3f v, float p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p) + 
                Fun.Abs(v.Z).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceSquared(this V3f a, V3f b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y) + Fun.Square(b.Z - a.Z);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V3f a, V3f b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance1(this V3f a, V3f b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y) + Fun.Abs(b.Z - a.Z);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V3f a, V3f b, float p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p) + Fun.Abs(b.Z - a.Z).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMax(this V3f a, V3f b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMin(this V3f a, V3f b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V3f query, V3f p0, V3f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            if (t <= 0) { return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V3f query, V3f p0, V3f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V3f query, V3f p0, V3f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            if (t <= 0) { t = 0; return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { t = 1; return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V3f query, V3f p0, V3f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        #endregion

        #region Operations

        /// <summary>
        /// Gets a copy of the given vector containing the reciprocal (1/x) of each element.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f Reciprocal(V3f v)
            => v.Reciprocal;

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V3f v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
            v.Z = -v.Z;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 3x3 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M33f Outer(this V3f a, V3f b)
        {
            return new M33f(
                        a.X * b.X, a.X * b.Y, a.X * b.Z, 
                        a.Y * b.X, a.Y * b.Y, a.Y * b.Z, 
                        a.Z * b.X, a.Z * b.Y, a.Z * b.Z);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Dot(this V3f a, V3f b)
        {
            return a.X * b.X + a.Y * b.Y + a.Z * b.Z;
        }

        /// <summary>
        /// Returns the skew-symmetric "cross" matrix (A^T = -A) of the vector v.
        /// </summary>
        public static M33f CrossMatrix(this V3f v)
        {
            return new M33f(0, -v.Z, +v.Y,
                            +v.Z, 0, -v.X,
                            -v.Y, +v.X, 0);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V3f v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeY;
            if (v.Z > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveZ;
            if (v.Z < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeZ;
            return flags;
        }

        /// <summary>
        /// Returns the reflection direction of the given vector v (pointing to the surface) for the given normal (should be normalized).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f Reflect(this V3f v, V3f normal)
        {
            return v - 2 * v.Dot(normal) * normal;
        }

        /// <summary>
        /// Returns the refraction direction of the given vector v (pointing to the surface) for the given normal and ratio of refraction indices (n_out / n_in).
        /// Both the input vectors should be normalized.
        /// Returns a zero-vector in case of total internal reflection.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f Refract(this V3f v, V3f normal, float eta)
        {
            var t = v.Dot(normal);
            var k = 1 - eta * eta * (1 - t * t);

            if (k < 0)
            {
                return V3f.Zero;
            }
            else
            {
                return eta * v - (eta * t + Fun.Sqrt(k)) * normal;
            }
        }

        /// <summary>
        /// Returns the cross product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f Cross(this V3f a, V3f b)
        {
            return new V3f(
            a.Y * b.Z - a.Z * b.Y,
            a.Z * b.X - a.X * b.Z,
            a.X * b.Y - a.Y * b.X
            );
        }

