        /// <summary>
        /// Returns whether the absolute value of any component of the given <see cref="V3f"/> is smaller than <paramref name="epsilon"/>.
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AnyTiny(this V3f v, float epsilon)
            => v.X.IsTiny(epsilon) || v.Y.IsTiny(epsilon) || v.Z.IsTiny(epsilon);

        /// <summary>
        /// Returns whether the absolute value of each component of the given <see cref="V3f"/> is smaller than <paramref name="epsilon"/>.
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllTiny(this V3f v, float epsilon)
            => v.X.IsTiny(epsilon) && v.Y.IsTiny(epsilon) && v.Z.IsTiny(epsilon);

