    public static class IRandomUniformV3fExtensions
    {
        #region IRandomUniform extensions for V3f

        /// <summary>
        /// Uses UniformFloat() to generate the elements of a V3f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3f(this IRandomUniform rnd)
        {
            return new V3f(rnd.UniformFloat(), rnd.UniformFloat(), rnd.UniformFloat());
        }

        /// <summary>
        /// Uses UniformFloat() to generate the elements of a V3f
        /// vector within the given Box3f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3f(this IRandomUniform rnd, Box3f box)
        {
            return new V3f(box.Min.X + rnd.UniformFloat() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloat() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformFloat() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformFloatClosed() to generate the elements of a V3f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fClosed(this IRandomUniform rnd)
        {
            return new V3f(rnd.UniformFloatClosed(), rnd.UniformFloatClosed(), rnd.UniformFloatClosed());
        }

        /// <summary>
        /// Uses UniformFloatClosed() to generate the elements of a V3f
        /// vector within the given Box3f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fClosed(this IRandomUniform rnd, Box3f box)
        {
            return new V3f(box.Min.X + rnd.UniformFloatClosed() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloatClosed() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformFloatClosed() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformFloatOpen() to generate the elements of a V3f vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fOpen(this IRandomUniform rnd)
        {
            return new V3f(rnd.UniformFloatOpen(), rnd.UniformFloatOpen(), rnd.UniformFloatOpen());
        }

        /// <summary>
        /// Uses UniformFloatOpen() to generate the elements of a V3f
        /// vector within the given Box3f.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fOpen(this IRandomUniform rnd, Box3f box)
        {
            return new V3f(box.Min.X + rnd.UniformFloatOpen() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformFloatOpen() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformFloatOpen() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Returns a uniformly distributed vector (corresponds to a
        /// uniformly distributed point on the surface of the unit sphere).
        /// Note however, that the returned vector will never be equal to
        /// [0, 0, -1]. Uses UniformFloat() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fDirection(this IRandomUniform rnd)
        {
            float phi = rnd.UniformFloat() * ConstantF.PiTimesTwo;
            float z = 1 - rnd.UniformFloat() * 2;
            float s = Fun.Sqrt(1 - z * z);
            return new V3f(Fun.Cos(phi) * s, Fun.Sin(phi) * s, z);
        }

        /// <summary>
        /// Uniform vector in the closed unit sphere (i.e vectors to
        /// the surface of the sphere may be generated). Uses UniformV3fClosed() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fClosedSphere(this IRandomUniform rnd)
        {
            float r2;
            V3f p;
            V3f c_shift = -V3f.Half;
            do
            {
                p = (rnd.UniformV3fClosed() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        /// <summary>
        /// Uniform vector inside the open unit sphere (i.e. no vector
        /// ends on the surface of the sphere). Uses UniformV3fOpen() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3f UniformV3fOpenSphere(this IRandomUniform rnd)
        {
            float r2;
            V3f p;
            V3f c_shift = -V3f.Half;
            do
            {
                p = (rnd.UniformV3fOpen() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        #endregion
    }

    #endregion

