        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d FromCubeFaceCode(int i) { return s_fromCubeCode[i]; }

        #endregion

        #region Norms

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        public readonly double LengthSquared
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return X * X  + Y * Y  + Z * Z ; }
        }

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        public readonly double Length
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                return Fun.Sqrt(X * X  + Y * Y  + Z * Z );
            }
        }

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        public readonly double Norm1
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Abs(X) + Fun.Abs(Y) + Fun.Abs(Z); }
        }

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        public readonly double Norm2
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Sqrt(X * X + Y * Y + Z * Z); }
        }

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        public readonly double NormMax
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Max(Fun.Abs(X), Fun.Abs(Y), Fun.Abs(Z)); }
        }

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        public readonly double NormMin
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get { return Fun.Min(Fun.Abs(X), Fun.Abs(Y), Fun.Abs(Z)); }
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        public readonly V3d Normalized
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get
            {
                var s = Length; if (s == 0) return V3d.Zero;
                s = 1 / s;
                return new V3d(X * s, Y * s, Z * s);
            }
        }

        /// <summary>
        /// Returns a copy of the vector with the maximum component length of
        /// exactly 1. This corresponds to mapping the vector onto an origin-
        /// centered cube with side length 2.
        /// </summary>
        public readonly V3d CubeMapped
        {
            get
            {
                double x = Fun.Abs(X);
                double y = Fun.Abs(Y);
                double z = Fun.Abs(Z);
                if (x > y)
                {
                    if (x > z)
                    {
                        double s = 1 / x;
                        return new V3d(Fun.Sign(X), Y * s, Z * s);
                    }
                    else
                    {
                        double s = 1 / z;
                        return new V3d(X * s, Y * s, Fun.Sign(Z));
                    }
                }
                else
                {
                    if (y > z)
                    {
                        double s = 1 / y;
                        return new V3d(X * s, Fun.Sign(Y), Z * s);
                    }
                    else
                    {
                        double s = 1 / z;
                        return new V3d(X * s, Y * s, Fun.Sign(Z));
                    }
                }
            }
        }

        /// <summary>
        /// Returns a copy of the vector with the maximum component length of
        /// exactly 1. This corresponds to mapping the vector onto an origin-
        /// centered cube with side length 2.
        /// The out parameter face indicate which face the vector was mapped to:
        /// 0 ... -XAxis, 1 ... -YAxis, 2 ... -ZAsix, 3 ... XAxis, 4 ... YAxis, 5 ... ZAxis.
        /// </summary>
        public readonly V3d CubeMappedOnFace(out int face)
        {
                double x = Fun.Abs(X);
                double y = Fun.Abs(Y);
                double z = Fun.Abs(Z);
                if (x > y)
                {
                    if (x > z)
                    {
                        double s = 1 / x; face = X < 0 ? 0 : 3;
                        return new V3d(Fun.Sign(X), Y * s, Z * s);
                    }
                    else
                    {
                        double s = 1 / z; face = Z < 0 ? 2 : 5;
                        return new V3d(X * s, Y * s, Fun.Sign(Z));
                    }
                }
                else
                {
                    if (y > z)
                    {
                        double s = 1 / y; face = Y < 0 ? 1 : 4;
                        return new V3d(X * s, Fun.Sign(Y), Z * s);
                    }
                    else
                    {
                        double s = 1 / z; face = Z < 0 ? 2 : 5;
                        return new V3d(X * s, Y * s, Fun.Sign(Z));
                    }
                }
        }

        /// <summary>
        /// Return an index for the cube face onto which the vector points.
        /// 0 ... -XAxis, 1 ... -YAxis, 2 ... -ZAsix, 3 ... XAxis, 4 ... YAxis, 5 ... ZAxis.
        /// </summary>
        public readonly int CubeFaceCode
        {
            get
            {
                double x = Fun.Abs(X);
                double y = Fun.Abs(Y);
                double z = Fun.Abs(Z);
                int c;
                double v;
                if (x > y)
                {
                    if (x > z) { c = 0; v = X; } else { c = 2; v = Z; }
                }
                else
                {
                    if (y > z) { c = 1; v = Y; } else { c = 2; v = Z; }
                }
                return v < 0 ? c : c + 3;
            }
        }

