        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (double)value; }
        }

        #endregion

        #region ISize3d Members

        public readonly V3d Size3d { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 3; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (double)value;
        }

        #endregion

    }

    public class V3dEqualityComparer : IEqualityComparer<V3d>
    {
        public static V3dEqualityComparer Default
            => new V3dEqualityComparer();

        #region IEqualityComparer<V3d> Members

        public bool Equals(V3d v0, V3d v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V3d v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

    public static partial class Fun
    {
        #region Min and Max

        /// <summary>
        /// Applies Fun.Min to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d Min(this V3d a, V3d b)
        {
            return new V3d(Min(a.X, b.X), Min(a.Y, b.Y), Min(a.Z, b.Z));
        }

        /// <summary>
        /// Applies Fun.Min to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d Min(this V3d a, double b)
        {
            return new V3d(Min(a.X, b), Min(a.Y, b), Min(a.Z, b));
        }

        /// <summary>
        /// Applies Fun.Min to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d Min(this double a, V3d b)
        {
            return new V3d(Min(a, b.X), Min(a, b.Y), Min(a, b.Z));
