        /// <summary>
        /// Returns the array of the index-th coordinate of each vector.
        /// </summary>
        public static double[] CopyCoord(this V3d[] self, int index)
        {
            switch (index)
            {
                case 0: return self.Map(v => v.X);
                case 1: return self.Map(v => v.Y);
                case 2: return self.Map(v => v.Z);
                default: throw new IndexOutOfRangeException();
            }
        }

        public static V3d WeightedSum(
                this V3d[] vectorArray, double[] weightArray)
        {
            var r = V3d.Zero;
            var count = vectorArray.LongLength;
            for (long i = 0; i < count; i++) r += vectorArray[i] * weightArray[i];
            return r;
        }

        #endregion
    }

    public static class IRandomUniformV3dExtensions
    {
        #region IRandomUniform extensions for V3d

        /// <summary>
        /// Uses UniformDouble() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3d(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDouble(), rnd.UniformDouble(), rnd.UniformDouble());
        }

        /// <summary>
        /// Uses UniformDouble() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3d(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDouble() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDouble() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDouble() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformDoubleClosed() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dClosed(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDoubleClosed(), rnd.UniformDoubleClosed(), rnd.UniformDoubleClosed());
        }

        /// <summary>
        /// Uses UniformDoubleClosed() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dClosed(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDoubleClosed() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDoubleClosed() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDoubleClosed() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformDoubleOpen() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dOpen(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDoubleOpen(), rnd.UniformDoubleOpen(), rnd.UniformDoubleOpen());
        }

        /// <summary>
        /// Uses UniformDoubleOpen() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dOpen(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDoubleOpen() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDoubleOpen() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDoubleOpen() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformDoubleFull() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFull(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDoubleFull(), rnd.UniformDoubleFull(), rnd.UniformDoubleFull());
        }

        /// <summary>
        /// Uses UniformDoubleFull() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFull(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDoubleFull() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDoubleFull() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDoubleFull() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformDoubleFullClosed() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullClosed(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDoubleFullClosed(), rnd.UniformDoubleFullClosed(), rnd.UniformDoubleFullClosed());
        }

        /// <summary>
        /// Uses UniformDoubleFullClosed() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullClosed(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDoubleFullClosed() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDoubleFullClosed() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDoubleFullClosed() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Uses UniformDoubleFullOpen() to generate the elements of a V3d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullOpen(this IRandomUniform rnd)
        {
            return new V3d(rnd.UniformDoubleFullOpen(), rnd.UniformDoubleFullOpen(), rnd.UniformDoubleFullOpen());
        }

        /// <summary>
        /// Uses UniformDoubleFullOpen() to generate the elements of a V3d
        /// vector within the given Box3d.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullOpen(this IRandomUniform rnd, Box3d box)
        {
            return new V3d(box.Min.X + rnd.UniformDoubleFullOpen() * (box.Max.X - box.Min.X), box.Min.Y + rnd.UniformDoubleFullOpen() * (box.Max.Y - box.Min.Y), box.Min.Z + rnd.UniformDoubleFullOpen() * (box.Max.Z - box.Min.Z));
        }

        /// <summary>
        /// Returns a uniformly distributed vector (corresponds to a
        /// uniformly distributed point on the surface of the unit sphere).
        /// Note however, that the returned vector will never be equal to
        /// [0, 0, -1]. Uses UniformDouble() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dDirection(this IRandomUniform rnd)
        {
            double phi = rnd.UniformDouble() * Constant.PiTimesTwo;
            double z = 1 - rnd.UniformDouble() * 2;
            double s = Fun.Sqrt(1 - z * z);
            return new V3d(Fun.Cos(phi) * s, Fun.Sin(phi) * s, z);
        }

        /// <summary>
        /// Uniform vector in the closed unit sphere (i.e vectors to
        /// the surface of the sphere may be generated). Uses UniformV3dClosed() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dClosedSphere(this IRandomUniform rnd)
        {
            double r2;
            V3d p;
            V3d c_shift = -V3d.Half;
            do
            {
                p = (rnd.UniformV3dClosed() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        /// <summary>
        /// Uniform vector inside the open unit sphere (i.e. no vector
        /// ends on the surface of the sphere). Uses UniformV3dOpen() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dOpenSphere(this IRandomUniform rnd)
        {
            double r2;
            V3d p;
            V3d c_shift = -V3d.Half;
            do
            {
                p = (rnd.UniformV3dOpen() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        /// <summary>
        /// Returns a uniformly distributed vector (corresponds to a
        /// uniformly distributed point on the surface of the unit sphere).
        /// Note however, that the returned vector will never be equal to
        /// [0, 0, -1]. Uses UniformDoubleFull() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullDirection(this IRandomUniform rnd)
        {
            double phi = rnd.UniformDoubleFull() * Constant.PiTimesTwo;
            double z = 1 - rnd.UniformDoubleFull() * 2;
            double s = Fun.Sqrt(1 - z * z);
            return new V3d(Fun.Cos(phi) * s, Fun.Sin(phi) * s, z);
        }

        /// <summary>
        /// Uniform vector in the closed unit sphere (i.e vectors to
        /// the surface of the sphere may be generated). Uses UniformV3dClosed() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullClosedSphere(this IRandomUniform rnd)
        {
            double r2;
            V3d p;
            V3d c_shift = -V3d.Half;
            do
            {
                p = (rnd.UniformV3dClosed() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        /// <summary>
        /// Uniform vector inside the open unit sphere (i.e. no vector
        /// ends on the surface of the sphere). Uses UniformV3dOpen() internally.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V3d UniformV3dFullOpenSphere(this IRandomUniform rnd)
        {
            double r2;
            V3d p;
            V3d c_shift = -V3d.Half;
            do
            {
                p = (rnd.UniformV3dOpen() + c_shift) * 2;
                r2 = p.LengthSquared;
            }
            while (r2 >= 1);
            return p;
        }

        #endregion
    }

