        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (int)value; }
        }

        #endregion

        #region ISize4i Members

        public readonly V4i Size4i { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 4; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (int)value;
        }

        #endregion

    }

    public class V4iEqualityComparer : IEqualityComparer<V4i>
    {
        public static V4iEqualityComparer Default
            => new V4iEqualityComparer();

        #region IEqualityComparer<V4i> Members

        public bool Equals(V4i v0, V4i v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V4i v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

