    public static class IRandomUniformV4iExtensions
    {
        #region IRandomUniform extensions for V4i

        /// <summary>
        /// Uses UniformInt() to generate the elements of a V4i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4i UniformV4i(this IRandomUniform rnd)
        {
            return new V4i(rnd.UniformInt(), rnd.UniformInt(), rnd.UniformInt(), rnd.UniformInt());
        }

        /// <summary>
        /// Uses UniformIntNonZero() to generate the elements of a V4i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4i UniformV4iNonZero(this IRandomUniform rnd)
        {
            return new V4i(rnd.UniformIntNonZero(), rnd.UniformIntNonZero(), rnd.UniformIntNonZero(), rnd.UniformIntNonZero());
        }

        /// <summary>
        /// Uses UniformInt(int) to generate the elements of a V4i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4i UniformV4i(this IRandomUniform rnd, int size)
        {
            return new V4i(rnd.UniformInt(size), rnd.UniformInt(size), rnd.UniformInt(size), rnd.UniformInt(size));
        }

        /// <summary>
        /// Uses UniformInt(int) to generate the elements of a V4i vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4i UniformV4i(this IRandomUniform rnd, V4i size)
        {
            return new V4i(rnd.UniformInt(size.X), rnd.UniformInt(size.Y), rnd.UniformInt(size.Z), rnd.UniformInt(size.W));
        }

        #endregion
    }

    #endregion

