        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (uint)value; }
        }

        #endregion

        #region ISize4ui Members

        public readonly V4ui Size4ui { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 4; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (uint)value;
        }

        #endregion

    }

    public class V4uiEqualityComparer : IEqualityComparer<V4ui>
    {
        public static V4uiEqualityComparer Default
            => new V4uiEqualityComparer();

        #region IEqualityComparer<V4ui> Members

        public bool Equals(V4ui v0, V4ui v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V4ui v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

