        #region Operations

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static uint Dot(this V4ui a, V4ui b)
        {
            return a.X * b.X + a.Y * b.Y + a.Z * b.Z + a.W * b.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V4ui v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > 0) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < 0) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > 0) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < 0) flags |= Aardbase.DirFlags.NegativeY;
            if (v.Z > 0) flags |= Aardbase.DirFlags.PositiveZ;
            if (v.Z < 0) flags |= Aardbase.DirFlags.NegativeZ;
            if (v.W > 0) flags |= Aardbase.DirFlags.PositiveW;
            if (v.W < 0) flags |= Aardbase.DirFlags.NegativeW;
            return flags;
        }

        #endregion

