        /// Returns the index of the element with the maximal Z coordinate
        /// within the list.
        /// </summary>
        public static int IndexOfMaxZ(this IList<V4ui> vectorArray, int count = 0)
        {
            var maximum = vectorArray[0].Z;
            int maxIndex = 0;
            if (count == 0) count = vectorArray.Count;
            for (int i = 1; i < count; i++)
            {
                var p = vectorArray[i].Z;
                if (p > maximum) { maximum = p; maxIndex = i; }
            }
            return maxIndex;
        }

        /// <summary>
        /// Returns the index of the element with the minimal W coordinate
        /// within the list.
        /// </summary>
        public static int IndexOfMinW(this IList<V4ui> vectorArray, int count = 0)
        {
            var minimum = vectorArray[0].W;
            int minIndex = 0;
            if (count == 0) count = vectorArray.Count;
            for (int i = 1; i < count; i++)
            {
                var p = vectorArray[i].W;
                if (p < minimum) { minimum = p; minIndex = i; }
            }
            return minIndex;
        }

        /// <summary>
        /// Returns the index of the element with the maximal W coordinate
        /// within the list.
        /// </summary>
        public static int IndexOfMaxW(this IList<V4ui> vectorArray, int count = 0)
        {
            var maximum = vectorArray[0].W;
            int maxIndex = 0;
            if (count == 0) count = vectorArray.Count;
            for (int i = 1; i < count; i++)
            {
                var p = vectorArray[i].W;
                if (p > maximum) { maximum = p; maxIndex = i; }
            }
            return maxIndex;
        }

        /// <summary>
        /// Returns the array of the index-th coordinate of each vector.
        /// </summary>
        public static uint[] CopyCoord(this V4ui[] self, int index)
        {
            switch (index)
            {
                case 0: return self.Map(v => v.X);
                case 1: return self.Map(v => v.Y);
                case 2: return self.Map(v => v.Z);
                case 3: return self.Map(v => v.W);
                default: throw new IndexOutOfRangeException();
            }
        }

        #endregion
    }

    public static class IRandomUniformV4uiExtensions
    {
        #region IRandomUniform extensions for V4ui

        /// <summary>
        /// Uses UniformUInt() to generate the elements of a V4ui vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4ui UniformV4ui(this IRandomUniform rnd)
        {
            return new V4ui(rnd.UniformUInt(), rnd.UniformUInt(), rnd.UniformUInt(), rnd.UniformUInt());
        }

        #endregion
    }

