        /// <summary>
        /// Number of elements in this vector.
        /// </summary>
        public const int Dimension = 4;

        /// <summary>
        /// All elements zero.
        /// </summary>
        public static V4l Zero
        {
            get { return new V4l(0, 0, 0, 0); }
        }


        /// <summary>
        /// All elements one.
        /// </summary>
        public static V4l One
        {
            get { return new V4l(1, 1, 1, 1); }
        }

        /// <summary>
        /// All elements set to maximum possible value.
        /// </summary>
        public static V4l MaxValue
        {
            get { return new V4l(Constant<long>.ParseableMaxValue, Constant<long>.ParseableMaxValue, Constant<long>.ParseableMaxValue, Constant<long>.ParseableMaxValue); }
        }

        /// <summary>
        /// All elements set to minimum possible value.
        /// </summary>
        public static V4l MinValue
        {
            get { return new V4l(Constant<long>.ParseableMinValue, Constant<long>.ParseableMinValue, Constant<long>.ParseableMinValue, Constant<long>.ParseableMinValue); }
        }

        /// <summary>
        /// Normalized X-axis.
        /// </summary>
        public static V4l XAxis
        {
            get { return new V4l(1, 0, 0, 0); }
        }

        /// <summary>
        /// Normalized Y-axis.
        /// </summary>
        public static V4l YAxis
        {
            get { return new V4l(0, 1, 0, 0); }
        }

        /// <summary>
        /// Normalized Z-axis.
        /// </summary>
        public static V4l ZAxis
        {
            get { return new V4l(0, 0, 1, 0); }
        }

        /// <summary>
        /// Normalized W-axis.
        /// </summary>
        public static V4l WAxis
        {
            get { return new V4l(0, 0, 0, 1); }
        }

        /// <summary>
        /// An array of accessor functions for the coordinates of the vector.
        /// </summary>
        public static readonly Func<V4l, long>[] SelectorArray =
            new Func<V4l, long>[] { v => v.X, v => v.Y, v => v.Z, v => v.W };

        /// <summary>
        /// Element getter function.
        /// </summary>
        public static readonly Func<V4l, int, long> Getter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    case 2: return v.Z;
                    case 3: return v.W;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action.
        /// </summary>
        public static readonly ActionRefValVal<V4l, int, long> Setter =
            (ref V4l v, int i, long s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    case 2: v.Z = s; return;
                    case 3: v.W = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element getter function with long index.
        /// </summary>
        public static readonly Func<V4l, long, long> LongGetter =
            (v, i) =>
            {
                switch (i)
                {
                    case 0: return v.X;
                    case 1: return v.Y;
                    case 2: return v.Z;
                    case 3: return v.W;
                    default: throw new IndexOutOfRangeException();
                }
            };

        /// <summary>
        /// Element setter action with long index.
        /// </summary>
        public static readonly ActionRefValVal<V4l, long, long> LongSetter =
            (ref V4l v, long i, long s) =>
            {
                switch (i)
                {
                    case 0: v.X = s; return;
                    case 1: v.Y = s; return;
                    case 2: v.Z = s; return;
                    case 3: v.W = s; return;
                    default: throw new IndexOutOfRangeException();
                }
            };

