        [DebuggerBrowsable(DebuggerBrowsableState.Never)]
        public readonly V4l WWWW => new V4l(W, W, W, W);

        #endregion

        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (long)value; }
        }

        #endregion

        #region ISize4l Members

        public readonly V4l Size4l { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 4; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (long)value;
        }

        #endregion

    }

    public class V4lEqualityComparer : IEqualityComparer<V4l>
    {
        public static V4lEqualityComparer Default
            => new V4lEqualityComparer();

        #region IEqualityComparer<V4l> Members

        public bool Equals(V4l v0, V4l v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V4l v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

