    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long LengthSquared(V4l v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Length(V4l v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d Normalized(V4l v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Norm1(V4l v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm2(V4l v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long NormMax(V4l v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long NormMin(V4l v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Norm(this V4l v, double p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p) + 
                Fun.Abs(v.Z).Pow(p) + 
                Fun.Abs(v.W).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceSquared(this V4l a, V4l b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y) + Fun.Square(b.Z - a.Z) + Fun.Square(b.W - a.W);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V4l a, V4l b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Distance1(this V4l a, V4l b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y) + Fun.Abs(b.Z - a.Z) + Fun.Abs(b.W - a.W);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double Distance(this V4l a, V4l b, double p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p) + Fun.Abs(b.Z - a.Z).Pow(p) + Fun.Abs(b.W - a.W).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceMax(this V4l a, V4l b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z), Fun.Abs(b.W - a.W));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long DistanceMin(this V4l a, V4l b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z), Fun.Abs(b.W - a.W));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V4l query, V4l p0, V4l p1)
        {
            return DistanceToLine((V4d) query, (V4d) p0, (V4d) p1);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V4l query, V4l p0, V4l p1)
        {
            return DistanceToInfiniteLine((V4d) query, (V4d) p0, (V4d) p1);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToLine(
                this V4l query, V4l p0, V4l p1, out double t)
        {
            return DistanceToLine((V4d) query, (V4d) p0, (V4d) p1, out t);
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static double DistanceToInfiniteLine(
                this V4l query, V4l p0, V4l p1, out double t)
        {
            return DistanceToInfiniteLine((V4d) query, (V4d) p0, (V4d) p1, out t);
        }

        #endregion

        #region Operations

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V4l v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
            v.Z = -v.Z;
            v.W = -v.W;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 4x4 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M44l Outer(this V4l a, V4l b)
        {
            return new M44l(
                        a.X * b.X, a.X * b.Y, a.X * b.Z, a.X * b.W, 
                        a.Y * b.X, a.Y * b.Y, a.Y * b.Z, a.Y * b.W, 
                        a.Z * b.X, a.Z * b.Y, a.Z * b.Z, a.Z * b.W, 
                        a.W * b.X, a.W * b.Y, a.W * b.Z, a.W * b.W);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Dot(this V4l a, V4l b)
        {
            return a.X * b.X + a.Y * b.Y + a.Z * b.Z + a.W * b.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V4l v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > 0) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < 0) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > 0) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < 0) flags |= Aardbase.DirFlags.NegativeY;
            if (v.Z > 0) flags |= Aardbase.DirFlags.PositiveZ;
            if (v.Z < 0) flags |= Aardbase.DirFlags.NegativeZ;
            if (v.W > 0) flags |= Aardbase.DirFlags.PositiveW;
            if (v.W < 0) flags |= Aardbase.DirFlags.NegativeW;
            return flags;
        }

        #endregion

        #region Comparisons

        /// <summary>
        /// Returns whether ALL elements of a are Smaller the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(this V4l a, V4l b)
        {
            return (a.X < b.X && a.Y < b.Y && a.Z < b.Z && a.W < b.W);
