        /// <summary>
        /// Returns the array of the index-th coordinate of each vector.
        /// </summary>
        public static long[] CopyCoord(this V4l[] self, int index)
        {
            switch (index)
            {
                case 0: return self.Map(v => v.X);
                case 1: return self.Map(v => v.Y);
                case 2: return self.Map(v => v.Z);
                case 3: return self.Map(v => v.W);
                default: throw new IndexOutOfRangeException();
            }
        }

        #endregion
    }

    public static class IRandomUniformV4lExtensions
    {
        #region IRandomUniform extensions for V4l

        /// <summary>
        /// Uses UniformLong() to generate the elements of a V4l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4l UniformV4l(this IRandomUniform rnd)
        {
            return new V4l(rnd.UniformLong(), rnd.UniformLong(), rnd.UniformLong(), rnd.UniformLong());
        }

        /// <summary>
        /// Uses UniformLongNonZero() to generate the elements of a V4l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4l UniformV4lNonZero(this IRandomUniform rnd)
        {
            return new V4l(rnd.UniformLongNonZero(), rnd.UniformLongNonZero(), rnd.UniformLongNonZero(), rnd.UniformLongNonZero());
        }

        /// <summary>
        /// Uses UniformLong(long) to generate the elements of a V4l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4l UniformV4l(this IRandomUniform rnd, long size)
        {
            return new V4l(rnd.UniformLong(size), rnd.UniformLong(size), rnd.UniformLong(size), rnd.UniformLong(size));
        }

        /// <summary>
        /// Uses UniformLong(long) to generate the elements of a V4l vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4l UniformV4l(this IRandomUniform rnd, V4l size)
