        #region Comparisons

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V4f a, V4f b)
        {
            return a.X == b.X && a.Y == b.Y && a.Z == b.Z && a.W == b.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(V4f v, float s)
        {
            return v.X == s && v.Y == s && v.Z == s && v.W == s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(float s, V4f v)
        {
            return s == v.X && s == v.Y && s == v.Z && s == v.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V4f a, V4f b)
        {
            return a.X != b.X || a.Y != b.Y || a.Z != b.Z || a.W != b.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(V4f v, float s)
        {
            return v.X != s || v.Y != s || v.Z != s || v.W != s;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(float s, V4f v)
        {
            return s != v.X || s != v.Y || s != v.Z || s != v.W;
        }

        #endregion

        #region IEquatable<V4f> Members

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly bool Equals(V4f other)
        {
            return X.Equals(other.X) && Y.Equals(other.Y) && Z.Equals(other.Z) && W.Equals(other.W);
        }

        #endregion

        #region Overrides

        public override readonly string ToString()
        {
            return ToString(null, CultureInfo.InvariantCulture);
        }

        public readonly string ToString(string format)
        {
            return ToString(format, CultureInfo.InvariantCulture);
        }

        public readonly string ToString(string format, IFormatProvider fp)
        {
            return ToString(format, fp, "[", ", ", "]");
        }

        /// <summary>
        /// Outputs e.g. a 3D-Vector in the form "(begin)x(between)y(between)z(end)".
        /// </summary>
        public readonly string ToString(string format, IFormatProvider fp, string begin, string between, string end)
        {
            if (fp == null) fp = CultureInfo.InvariantCulture;
            return begin + X.ToString(format, fp)  + between + Y.ToString(format, fp)  + between + Z.ToString(format, fp)  + between + W.ToString(format, fp)  + end;
        }

        public override readonly int GetHashCode()
        {
            return HashCode.GetCombined(X, Y, Z, W);
        }

        public override readonly bool Equals(object other)
            => (other is V4f o) ? Equals(o) : false;

        public readonly Text ToText(int bracketLevel = 1)
        {
            return
                ((bracketLevel == 1 ? "[" : "")
                + X.ToString(null, CultureInfo.InvariantCulture)  + ", " 
                + Y.ToString(null, CultureInfo.InvariantCulture)  + ", " 
                + Z.ToString(null, CultureInfo.InvariantCulture)  + ", " 
                + W.ToString(null, CultureInfo.InvariantCulture) 
                + (bracketLevel == 1 ? "]" : "")).ToText();
        }

        #endregion

        #region Parsing

        public static V4f Parse(string s)
        {
            var x = s.NestedBracketSplitLevelOne().ToArray();
            return new V4f(
                float.Parse(x[0], CultureInfo.InvariantCulture), 
                float.Parse(x[1], CultureInfo.InvariantCulture), 
                float.Parse(x[2], CultureInfo.InvariantCulture), 
                float.Parse(x[3], CultureInfo.InvariantCulture)
            );
        }

        public static V4f Parse(Text t)
        {
            return t.NestedBracketSplit(1, Text<float>.Parse, V4f.Setter);
        }

        public static V4f Parse(Text t, int bracketLevel)
        {
            return t.NestedBracketSplit(bracketLevel, Text<float>.Parse, V4f.Setter);
        }

        #endregion

