        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (float)value; }
        }

        #endregion

        #region ISize4f Members

        public readonly V4f Size4f { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 4; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (float)value;
        }

        #endregion

    }

    public class V4fEqualityComparer : IEqualityComparer<V4f>
    {
        public static V4fEqualityComparer Default
            => new V4fEqualityComparer();

        #region IEqualityComparer<V4f> Members

        public bool Equals(V4f v0, V4f v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V4f v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

