            return new V4f(InvLerp(y.X, a.X, b.X), InvLerp(y.Y, a.Y, b.Y), InvLerp(y.Z, a.Z, b.Z), InvLerp(y.W, a.W, b.W));
        }

        #endregion

        #region Floating point bits

        /// <summary>
        /// Applies Fun.FloatToBits to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4i FloatToBits(this V4f x)
        {
            return new V4i(FloatToBits(x.X), FloatToBits(x.Y), FloatToBits(x.Z), FloatToBits(x.W));
        }

        /// <summary>
        /// Applies Fun.FloatToUnsignedBits to each element of the given vector(s).
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4ui FloatToUnsignedBits(this V4f x)
        {
            return new V4ui(FloatToUnsignedBits(x.X), FloatToUnsignedBits(x.Y), FloatToUnsignedBits(x.Z), FloatToUnsignedBits(x.W));
        }

        #endregion

        #region ApproximateEquals

        /// <summary>
        /// Returns whether the given vectors are equal within the given tolerance.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool ApproximateEquals(this V4f a, V4f b, float tolerance)
        {
            return ApproximateEquals(a.X, b.X, tolerance) && ApproximateEquals(a.Y, b.Y, tolerance) && ApproximateEquals(a.Z, b.Z, tolerance) && ApproximateEquals(a.W, b.W, tolerance);
        }

        /// <summary>
        /// Returns whether the given vectors are equal within
        /// Constant{float}.PositiveTinyValue.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool ApproximateEquals(this V4f a, V4f b)
        {
            return ApproximateEquals(a, b, Constant<float>.PositiveTinyValue);
        }


        #endregion

        #region IsTiny

        /// <summary>
        /// Returns whether the absolute value of each component of the given <see cref="V4f"/> is smaller than <paramref name="epsilon"/>.
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool IsTiny(this V4f v, float epsilon)
            => Vec.AllTiny(v, epsilon);

        /// <summary>
        /// Returns whether the absolute value of each component of the given <see cref="V4f"/> is smaller than Constant&lt;float&gt;.PositiveTinyValue.
        /// </summary>
        [Pure]
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool IsTiny(V4f v)
            => v.IsTiny;

        #endregion

