        /// <summary>
        /// Returns whether any component of the given <see cref="V4f"/> is NaN.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool IsNaN(V4f v)
            => v.IsNaN;

        /// <summary>
        /// Returns whether any component of the the given <see cref="V4f"/> is infinity (positive or negative).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool IsInfinity(V4f v)
            => v.IsInfinity;

        /// <summary>
