    /// <summary>
    /// Contains static methods
    /// </summary>
    public static partial class Vec
    {
        #region Length

        /// <summary>
        /// Returns the squared length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float LengthSquared(V4f v)
            => v.LengthSquared;

        /// <summary>
        /// Returns the length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Length(V4f v)
            => v.Length;

        #endregion

        #region Normalize

        /// <summary>
        /// Normalizes the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Normalize(this ref V4f v)
        {
            var s = v.Length; if (s == 0) return;
            s = 1 / s;
            v.X *= s;
            v.Y *= s;
            v.Z *= s;
            v.W *= s;
        }

        /// <summary>
        /// Returns a normalized copy of this vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f Normalized(V4f v)
            => v.Normalized;

        #endregion

        #region Norms

        /// <summary>
        /// Returns the Manhattan (or 1-) norm of the vector. This is
        /// calculated as |x| + |y| + ...
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm1(V4f v)
            => v.Norm1;

        /// <summary>
        /// Returns the Euclidean (or 2-) norm of the vector. This is the
        /// length of the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm2(V4f v)
            => v.Norm2;

        /// <summary>
        /// Returns the infinite (or maximum) norm of the vector. This is
        /// calculated as max(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMax(V4f v)
            => v.NormMax;

        /// <summary>
        /// Returns the minimum norm of the vector. This is calculated as
        /// min(|x|, |y|, ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float NormMin(V4f v)
            => v.NormMin;

        /// <summary>
        /// Gets the p-norm. This is calculated as the p-th root of (|x|^n + |y|^n + ...).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Norm(this V4f v, float p)
        {
            return (
                Fun.Abs(v.X).Pow(p) + 
                Fun.Abs(v.Y).Pow(p) + 
                Fun.Abs(v.Z).Pow(p) + 
                Fun.Abs(v.W).Pow(p)).Pow(1 / p);
        }

        #endregion

        #region Distance functions

        /// <summary>
        /// Returns the squared distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceSquared(this V4f a, V4f b)
            => Fun.Square(b.X - a.X) + Fun.Square(b.Y - a.Y) + Fun.Square(b.Z - a.Z) + Fun.Square(b.W - a.W);

        /// <summary>
        /// Returns the distance between the given points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V4f a, V4f b)
            => Fun.Sqrt(DistanceSquared(a, b));

        /// <summary>
        /// Returns the Manhatten (or 1-) distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance1(this V4f a, V4f b)
            => Fun.Abs(b.X - a.X) + Fun.Abs(b.Y - a.Y) + Fun.Abs(b.Z - a.Z) + Fun.Abs(b.W - a.W);

        /// <summary>
        /// Returns the p-distance between two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Distance(this V4f a, V4f b, float p)
            => (Fun.Abs(b.X - a.X).Pow(p) + Fun.Abs(b.Y - a.Y).Pow(p) + Fun.Abs(b.Z - a.Z).Pow(p) + Fun.Abs(b.W - a.W).Pow(p)).Pow(1 / p);

        /// <summary>
        /// Returns the maximal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMax(this V4f a, V4f b)
            => Fun.Max(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z), Fun.Abs(b.W - a.W));

        /// <summary>
        /// Returns the minimal absolute distance between the components of
        /// the two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceMin(this V4f a, V4f b)
            => Fun.Min(Fun.Abs(b.X - a.X), Fun.Abs(b.Y - a.Y), Fun.Abs(b.Z - a.Z), Fun.Abs(b.W - a.W));

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V4f query, V4f p0, V4f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            if (t <= 0) { return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V4f query, V4f p0, V4f p1)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            var t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the line segment defined by the two supplied line end
        /// points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToLine(
                this V4f query, V4f p0, V4f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            if (t <= 0) { t = 0; return p0q.Length; }
            var denom = p0p1.LengthSquared;
            if (t >= denom) { t = 1; return Distance(query, p1); }
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        /// <summary>
        /// Returns the minimal euclidean distance between the supplied query
        /// point and the infinite line defined by two points.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float DistanceToInfiniteLine(
                this V4f query, V4f p0, V4f p1, out float t)
        {
            var p0p1 = p1 - p0;
            var p0q = query - p0;
            t = Dot(p0q, p0p1);
            var denom = p0p1.LengthSquared;
            t /= denom;
            return (p0q - t * p0p1).Length;
        }

        #endregion

        #region Operations

        /// <summary>
        /// Gets a copy of the given vector containing the reciprocal (1/x) of each element.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f Reciprocal(V4f v)
            => v.Reciprocal;

        /// <summary>
        /// Negates the vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Negate(this ref V4f v)
        {
            v.X = -v.X;
            v.Y = -v.Y;
            v.Z = -v.Z;
            v.W = -v.W;
        }

        /// <summary>
        /// Returns the outer product (tensor-product) of a * b^T as a 4x4 matrix.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static M44f Outer(this V4f a, V4f b)
        {
            return new M44f(
                        a.X * b.X, a.X * b.Y, a.X * b.Z, a.X * b.W, 
                        a.Y * b.X, a.Y * b.Y, a.Y * b.Z, a.Y * b.W, 
                        a.Z * b.X, a.Z * b.Y, a.Z * b.Z, a.Z * b.W, 
                        a.W * b.X, a.W * b.Y, a.W * b.Z, a.W * b.W);
        }

        /// <summary>
        /// Returns the dot product of two vectors.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static float Dot(this V4f a, V4f b)
        {
            return a.X * b.X + a.Y * b.Y + a.Z * b.Z + a.W * b.W;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static DirFlags DirFlags(this V4f v)
        {
            DirFlags flags = Aardbase.DirFlags.None;
            if (v.X > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveX;
            if (v.X < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeX;
            if (v.Y > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveY;
            if (v.Y < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeY;
            if (v.Z > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveZ;
            if (v.Z < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeZ;
            if (v.W > Constant<float>.PositiveTinyValue) flags |= Aardbase.DirFlags.PositiveW;
            if (v.W < Constant<float>.NegativeTinyValue) flags |= Aardbase.DirFlags.NegativeW;
            return flags;
        }

        /// <summary>
        /// Returns the reflection direction of the given vector v (pointing to the surface) for the given normal (should be normalized).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f Reflect(this V4f v, V4f normal)
        {
            return v - 2 * v.Dot(normal) * normal;
        }

        /// <summary>
        /// Returns the refraction direction of the given vector v (pointing to the surface) for the given normal and ratio of refraction indices (n_out / n_in).
        /// Both the input vectors should be normalized.
        /// Returns a zero-vector in case of total internal reflection.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f Refract(this V4f v, V4f normal, float eta)
        {
            var t = v.Dot(normal);
            var k = 1 - eta * eta * (1 - t * t);

            if (k < 0)
            {
                return V4f.Zero;
            }
            else
            {
                return eta * v - (eta * t + Fun.Sqrt(k)) * normal;
            }
        }

        #endregion

        #region Comparisons

        /// <summary>
        /// Returns whether ALL elements of a are Smaller the corresponding element of b.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool AllSmaller(this V4f a, V4f b)
        {
            return (a.X < b.X && a.Y < b.Y && a.Z < b.Z && a.W < b.W);
        }

        /// <summary>
        /// Returns whether ALL elements of v are Smaller s.
        /// ATTENTION: For example (AllSmaller(a,b)) is not the same as !(AllGreaterOrEqual(a,b)) but !(AnyGreaterOrEqual(a,b)).
