        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, ref Tup2<float> w)
        {
            return p0 * w.E0 + p1 * w.E1;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, V4f p2, ref Tup3<float> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, V4f p2, V4f p3, ref Tup4<float> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, V4f p2, V4f p3, V4f p4, ref Tup5<float> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, V4f p2, V4f p3, V4f p4, V4f p5, ref Tup6<float> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4 + p5 * w.E5;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4f LinCom(V4f p0, V4f p1, V4f p2, V4f p3, V4f p4, V4f p5, V4f p6, ref Tup7<float> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4 + p5 * w.E5 + p6 * w.E6;
        }

