        #region IVector<double> Members

        /// <summary>
        /// By using long indices, the IVector&lt;double&gt; interface is
        /// accessed.
        /// </summary>
        public double this[long i]
        {
            readonly get { return (double)this[(int)i]; }
            set { this[(int)i] = (double)value; }
        }

        #endregion

        #region ISize4d Members

        public readonly V4d Size4d { get { return this; } }

        #endregion

        #region IVector

        public readonly long Dim
        {
            get { return 4; }
        }

        public readonly object GetValue(long index)
        {
            return (object)this[(int)index];
        }

        public void SetValue(object value, long index)
        {
            this[(int)index] = (double)value;
        }

        #endregion

    }

    public class V4dEqualityComparer : IEqualityComparer<V4d>
    {
        public static V4dEqualityComparer Default
            => new V4dEqualityComparer();

        #region IEqualityComparer<V4d> Members

        public bool Equals(V4d v0, V4d v1)
        {
            return v0 == v1;
        }

        public int GetHashCode(V4d v)
        {
            return v.GetHashCode();
        }

        #endregion
    }

