        #region Linear Combination

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, ref Tup2<double> w)
        {
            return p0 * w.E0 + p1 * w.E1;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, V4d p2, ref Tup3<double> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, V4d p2, V4d p3, ref Tup4<double> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, V4d p2, V4d p3, V4d p4, ref Tup5<double> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, V4d p2, V4d p3, V4d p4, V4d p5, ref Tup6<double> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4 + p5 * w.E5;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d LinCom(V4d p0, V4d p1, V4d p2, V4d p3, V4d p4, V4d p5, V4d p6, ref Tup7<double> w)
        {
            return p0 * w.E0 + p1 * w.E1 + p2 * w.E2 + p3 * w.E3 + p4 * w.E4 + p5 * w.E5 + p6 * w.E6;
        }

