        #region ArrayExtensions

        public static int IndexOfClosestPoint(this V4d[] pointArray, V4d point)
        {
            var bestDist = DistanceSquared(point, pointArray[0]);
            int bestIndex = 0;
            int count = pointArray.Length;
            for (int i = 1; i < count; i++)
            {
                var dist = DistanceSquared(point, pointArray[i]);
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

        public static int IndexOfClosestPoint(
                this V4d[] array, int start, int count,
                V4d point)
        {
            var bestDist = DistanceSquared(point, array[start]);
            int bestIndex = 0;
            for (int i = start + 1, e = start + count; i < e; i++)
            {
                var dist = DistanceSquared(point, array[i]);
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

        public static int IndexOfClosestPoint<T>(
                this T[] array, int start, int count,
                Func<T, V4d> pointSelector, V4d point)
        {
            var bestDist = DistanceSquared(point, pointSelector(array[start]));
            int bestIndex = 0;
            for (int i = start + 1, e = start + count; i < e; i++)
            {
                var dist = DistanceSquared(point, pointSelector(array[i]));
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

        public static long LongIndexOfClosestPoint(this V4d[] pointArray, V4d point)
        {
            var bestDist = DistanceSquared(point, pointArray[0]);
            long bestIndex = 0;
            long count = pointArray.LongLength;
            for (long i = 1; i < count; i++)
            {
                var dist = DistanceSquared(point, pointArray[i]);
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

        public static long LongIndexOfClosestPoint(
                this V4d[] array, long start, long count,
                V4d point)
        {
            var bestDist = DistanceSquared(point, array[start]);
            long bestIndex = 0;
            for (long i = start + 1, e = start + count; i < e; i++)
            {
                var dist = DistanceSquared(point, array[i]);
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

        public static long LongIndexOfClosestPoint<T>(
                this T[] array, long start, long count,
                Func<T, V4d> pointSelector, V4d point)
        {
            var bestDist = DistanceSquared(point, pointSelector(array[start]));
            long bestIndex = 0;
            for (long i = start + 1, e = start + count; i < e; i++)
            {
                var dist = DistanceSquared(point, pointSelector(array[i]));
                if (dist < bestDist) { bestDist = dist; bestIndex = i; }
            }
            return bestIndex;
        }

