        /// <summary>
        /// Returns the array of the index-th coordinate of each vector.
        /// </summary>
        public static double[] CopyCoord(this V4d[] self, int index)
        {
            switch (index)
            {
                case 0: return self.Map(v => v.X);
                case 1: return self.Map(v => v.Y);
                case 2: return self.Map(v => v.Z);
                case 3: return self.Map(v => v.W);
                default: throw new IndexOutOfRangeException();
            }
        }

        public static V4d WeightedSum(
                this V4d[] vectorArray, double[] weightArray)
        {
            var r = V4d.Zero;
            var count = vectorArray.LongLength;
            for (long i = 0; i < count; i++) r += vectorArray[i] * weightArray[i];
            return r;
        }

        #endregion
    }

    public static class IRandomUniformV4dExtensions
    {
        #region IRandomUniform extensions for V4d

        /// <summary>
        /// Uses UniformDouble() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4d(this IRandomUniform rnd)
        {
            return new V4d(rnd.UniformDouble(), rnd.UniformDouble(), rnd.UniformDouble(), rnd.UniformDouble());
        }

        /// <summary>
        /// Uses UniformDoubleClosed() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4dClosed(this IRandomUniform rnd)
        {
            return new V4d(rnd.UniformDoubleClosed(), rnd.UniformDoubleClosed(), rnd.UniformDoubleClosed(), rnd.UniformDoubleClosed());
        }

        /// <summary>
        /// Uses UniformDoubleOpen() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4dOpen(this IRandomUniform rnd)
        {
            return new V4d(rnd.UniformDoubleOpen(), rnd.UniformDoubleOpen(), rnd.UniformDoubleOpen(), rnd.UniformDoubleOpen());
        }

        /// <summary>
        /// Uses UniformDoubleFull() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4dFull(this IRandomUniform rnd)
        {
            return new V4d(rnd.UniformDoubleFull(), rnd.UniformDoubleFull(), rnd.UniformDoubleFull(), rnd.UniformDoubleFull());
        }

        /// <summary>
        /// Uses UniformDoubleFullClosed() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4dFullClosed(this IRandomUniform rnd)
        {
            return new V4d(rnd.UniformDoubleFullClosed(), rnd.UniformDoubleFullClosed(), rnd.UniformDoubleFullClosed(), rnd.UniformDoubleFullClosed());
        }

        /// <summary>
        /// Uses UniformDoubleFullOpen() to generate the elements of a V4d vector.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static V4d UniformV4dFullOpen(this IRandomUniform rnd)
